(function() {
    'use strict';

    class PasoSeguroAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Emprendimiento Social: Paso Seguro';
            this.version = '1.1.0';
            // Pre-round domainState snapshots so Undo can roll state back instead
            // of re-accumulating on resubmit (see initialize / calculateResults).
            this._snap = [];

            this.STRATEGIES = {
                A: { cost: 750, maxBonus: 400, successRate: 0.80, impactMult: 0.60, repCost: 0 },
                B: { cost: 1000, maxBonus: 750, successRate: 0.55, impactMult: 0.85, repCost: 0 },
                C: { cost: 1000, maxBonus: 650, successRate: 0.75, impactMult: 1.0, repCost: 0 },
                D: { cost: 200, maxBonus: 0, successRate: 1.0, impactMult: 1.5, repCost: 20 },
                E: { cost: 350, maxBonus: 150, successRate: 0.45, impactMult: 0.55, repCost: 0 }
            };

            this.BRIEFINGS = {
                es: [
                    {
                        title: 'Ronda 1 — Análisis Financiero de Viabilidad',
                        text: '<b>Paso Seguro S.A.S.</b>, empresa social de reintegración de ex-combatientes en Medellín, enfrenta una crisis existencial.<br><br>El gobierno redujo el financiamiento de Paz Total en 62.5%. La Fundación Open Society cierra su programa en Colombia (último pago: COP 300M en junio 2026). Los ingresos operacionales crecen solo al 12–25% anual, lejos del 100% proyectado.<br><br><b>Su tarea:</b> Redimensione la organización para reducir costos. Elija cuántos ex-combatientes y especialistas mantener, y en cuántas ciudades operar. El sistema calculará la nueva estructura de costos y brecha financiera.<br><br><b>Datos clave:</b> Costo actual: COP 1,200M/año | Ingresos operación: COP 280M | Gobierno 2026: COP 180M | Último pago ONG: COP 300M'
                    },
                    {
                        title: 'Ronda 2 — Selección de Estrategia de Pivote',
                        text: 'Con la nueva estructura de costos definida, elija una estrategia para alcanzar sostenibilidad financiera a partir de 2027 (sin financiamiento ONG, gobierno reducido a COP 100M).<br><br><b>Opciones:</b><br>• A — Reducir escala, mantener misión central (costo COP 750M, break-even 2–3 años)<br>• B — Pivotar a consultoría B2B premium para multinacionales (costo COP 1,000M, alto potencial pero riesgo elevado)<br>• C — Contrato multi-año con gobierno como proveedor de reintegración (costo COP 1,000M, break-even rápido, riesgo político)<br>• D — Fusión con SENA u otra institución mayor (elimina presión financiera, pérdida de independencia)<br>• E — Reinventar como plataforma digital de colocación laboral (costo COP 350M, modelo escalable, requiere desarrollo tech)<br><br>Determine también qué porcentaje de recursos invertir en crecimiento vs. operación actual.'
                    },
                    {
                        title: 'Ronda 3 — Negociación y Recaudación de Fondos',
                        text: 'Debe asegurar financiamiento puente para los próximos 24 meses mientras ejecuta la transformación estratégica.<br><br>Distribuya su esfuerzo de recaudación entre tres fuentes:<br>• <b>Gobierno:</b> Proponer contrato con Ministerio de Inclusión Social. ROI social: cada ex-combatiente empleado ahorra costos de seguridad (potencial: COP 500–800M)<br>• <b>Donantes internacionales:</b> Buscar nuevos donantes para reemplazar Open Society con caso de impacto demostrado: 127 beneficiarios, 68% retención (potencial: COP 200–400M)<br>• <b>Inversores de impacto:</b> Ofrecer quasi-equity con retorno social + financiero modesto 2–5% (potencial: COP 150–300M)<br><br>La probabilidad de éxito depende del esfuerzo asignado y la coherencia con la estrategia elegida en Ronda 2.'
                    },
                    {
                        title: 'Ronda 4 — Dilema Ético: Financiamiento Cuestionable',
                        text: 'A dos semanas de cerrar negociaciones, el CEO recibe una llamada de un intermediario: un grupo empresarial de Medellín ofrece <b>COP 1,500 millones</b> en financiamiento para Paso Seguro, sin condiciones específicas.<br><br><b>El grupo:</b> Públicamente una constructora exitosa. Pero existen rumores persistentes de vínculos con grupos armados. El financiamiento podría ser lavado de dinero disfrazado de causa social.<br><br><b>La tentación:</b> COP 1,500M resuelve el 100% del problema de financiamiento por 1.5 años.<br><b>El riesgo:</b> Comprometer la integridad de una empresa dedicada a reintegración de ex-combatientes, riesgo legal y regulatorio, pérdida de credibilidad ante gobierno y donantes.<br><br>Decida si acepta o rechaza, qué nivel de due diligence realizar, y cuánta transparencia mantener con su equipo.'
                    }
                ],
                en: [
                    {
                        title: 'Round 1 — Financial Viability Analysis',
                        text: '<b>Paso Seguro S.A.S.</b>, a social enterprise for ex-combatant reintegration in Medellin, faces an existential crisis.<br><br>The government cut Peace Total funding by 62.5%. The Open Society Foundation is closing its Colombia program (last payment: COP 300M in June 2026). Operating revenue grows only at 12–25% annually, far from the projected 100%.<br><br><b>Your task:</b> Resize the organization to reduce costs. Choose how many ex-combatants and specialists to retain, and in how many cities to operate. The system will calculate the new cost structure and financial gap.<br><br><b>Key data:</b> Current cost: COP 1,200M/year | Operating revenue: COP 280M | Government 2026: COP 180M | Last NGO payment: COP 300M'
                    },
                    {
                        title: 'Round 2 — Strategic Pivot Selection',
                        text: 'With the new cost structure defined, choose a strategy to achieve financial sustainability from 2027 onward (no NGO funding, government reduced to COP 100M).<br><br><b>Options:</b><br>• A — Reduce scale, maintain core mission (cost COP 750M, break-even 2–3 years)<br>• B — Pivot to premium B2B consulting for multinationals (cost COP 1,000M, high potential but elevated risk)<br>• C — Multi-year government contract as reintegration provider (cost COP 1,000M, fast break-even, political risk)<br>• D — Merger with SENA or similar institution (eliminates financial pressure, loss of independence)<br>• E — Reinvent as digital job placement platform (cost COP 350M, scalable model, requires tech development)<br><br>Also determine what percentage of resources to invest in growth vs. current operations.'
                    },
                    {
                        title: 'Round 3 — Negotiation and Fundraising',
                        text: 'You must secure bridge funding for the next 24 months while executing the strategic transformation.<br><br>Distribute your fundraising effort across three sources:<br>• <b>Government:</b> Propose contract with Ministry of Social Inclusion. Social ROI: each employed ex-combatant saves security costs (potential: COP 500–800M)<br>• <b>International donors:</b> Seek new donors to replace Open Society with proven impact case: 127 beneficiaries, 68% retention (potential: COP 200–400M)<br>• <b>Impact investors:</b> Offer quasi-equity with social + modest financial return of 2–5% (potential: COP 150–300M)<br><br>Success probability depends on effort allocated and coherence with the strategy chosen in Round 2.'
                    },
                    {
                        title: 'Round 4 — Ethical Dilemma: Questionable Funding',
                        text: 'Two weeks before closing negotiations, the CEO receives a call from an intermediary: a business group from Medellin offers <b>COP 1,500 million</b> in funding for Paso Seguro, with no specific conditions.<br><br><b>The group:</b> Publicly a successful construction company. But persistent rumors of ties to armed groups exist. The funding could be money laundering disguised as social cause.<br><br><b>The temptation:</b> COP 1,500M solves 100% of the funding problem for 1.5 years.<br><b>The risk:</b> Compromising the integrity of an enterprise dedicated to ex-combatant reintegration, legal and regulatory risk, loss of credibility with government and donors.<br><br>Decide whether to accept or reject, what level of due diligence to perform, and how much transparency to maintain with your team.'
                    }
                ]
            };
        }

        _getLang() {
            var htmlLang = document.documentElement.lang || 'es';
            return htmlLang.startsWith('en') ? 'en' : 'es';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, 3);
            var lang = this._getLang();
            var briefing = this.BRIEFINGS[lang][idx];
            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = briefing.title;
            var textEl = document.getElementById('briefingText');
            if (textEl) textEl.innerHTML = briefing.text;
            for (var i = 1; i <= 4; i++) {
                var panel = document.getElementById('round' + i + 'Controls');
                if (panel) panel.style.display = (i === idx + 1) ? 'block' : 'none';
            }
        }

        _setupInteractiveControls() {
            var exSlider = document.getElementById('exCombatantsInput');
            var exVal = document.getElementById('exCombatantsValue');
            if (exSlider && exVal) {
                exSlider.addEventListener('input', function() { exVal.textContent = exSlider.value; });
            }
            var spSlider = document.getElementById('specialistsInput');
            var spVal = document.getElementById('specialistsValue');
            if (spSlider && spVal) {
                spSlider.addEventListener('input', function() { spVal.textContent = spSlider.value; });
            }
            var grSlider = document.getElementById('growthInvestInput');
            var grVal = document.getElementById('growthInvestValue');
            if (grSlider && grVal) {
                grSlider.addEventListener('input', function() { grVal.textContent = grSlider.value + '%'; });
            }
            var govIn = document.getElementById('govAllocInput');
            var donIn = document.getElementById('donorAllocInput');
            var invIn = document.getElementById('investorAllocInput');
            var totDisp = document.getElementById('totalAllocDisplay');
            function updateTot() {
                if (!govIn || !donIn || !invIn || !totDisp) return;
                var t = (parseInt(govIn.value) || 0) + (parseInt(donIn.value) || 0) + (parseInt(invIn.value) || 0);
                totDisp.textContent = t + '%';
                totDisp.style.color = t === 100 ? '#059669' : '#dc2626';
            }
            if (govIn) govIn.addEventListener('input', updateTot);
            if (donIn) donIn.addEventListener('input', updateTot);
            if (invIn) invIn.addEventListener('input', updateTot);
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    annualCost: 1200,
                    annualRevenue: 280,
                    govFunding: 180,
                    ongFunding: 300,
                    externalFunding: 0,
                    totalFunds: 760,
                    gap: 440,
                    beneficiaries: 127,
                    reputation: 100,
                    employees: 35,
                    exCombatants: 18,
                    specialists: 12,
                    cities: 3,
                    strategy: '',
                    gapHistory: [],
                    beneficiaryHistory: [],
                    reputationHistory: [],
                    fundingHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    numExCombatants: 18,
                    numSpecialists: 12,
                    numCities: 3,
                    strategy: 'A',
                    growthInvestment: 50,
                    govAlloc: 40,
                    donorAlloc: 30,
                    investorAlloc: 30,
                    acceptFunding: 0,
                    dueDiligence: 1,
                    transparency: 1
                };
            }
            this._setupInteractiveControls();
            // Undo support: the framework's Undo pops the last history row,
            // decrements currentPeriod and re-calls initialize() WITHOUT rolling
            // domainState back. If we hold more snapshots than history rows, an
            // Undo just happened -> restore the pre-round domainState so funds /
            // gap / beneficiaries / reputation / history revert instead of drifting.
            var histLen = (state.history && state.history.length) || 0;
            if (this._snap && this._snap.length > histLen) {
                state.domainState = this._snap.pop();
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var exIn = document.getElementById('exCombatantsInput');
                var spIn = document.getElementById('specialistsInput');
                var ciIn = document.getElementById('citiesInput');
                if (exIn) decisions.numExCombatants = parseInt(exIn.value);
                if (spIn) decisions.numSpecialists = parseInt(spIn.value);
                if (ciIn) decisions.numCities = parseInt(ciIn.value);
            } else if (period === 2) {
                var stIn = document.getElementById('strategyInput');
                var grIn = document.getElementById('growthInvestInput');
                if (stIn) decisions.strategy = stIn.value;
                if (grIn) decisions.growthInvestment = parseInt(grIn.value);
            } else if (period === 3) {
                var gIn = document.getElementById('govAllocInput');
                var dIn = document.getElementById('donorAllocInput');
                var iIn = document.getElementById('investorAllocInput');
                if (gIn) decisions.govAlloc = parseInt(gIn.value) || 0;
                if (dIn) decisions.donorAlloc = parseInt(dIn.value) || 0;
                if (iIn) decisions.investorAlloc = parseInt(iIn.value) || 0;
                var total = decisions.govAlloc + decisions.donorAlloc + decisions.investorAlloc;
                if (total !== 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('alloc_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 4) {
                var afIn = document.getElementById('acceptFundingInput');
                var ddIn = document.getElementById('dueDiligenceInput');
                var trIn = document.getElementById('transparencyInput');
                if (afIn) decisions.acceptFunding = parseInt(afIn.value);
                if (ddIn) decisions.dueDiligence = parseInt(ddIn.value);
                if (trIn) decisions.transparency = parseInt(trIn.value);
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            // Snapshot the pre-round domainState (serializable) so Undo can roll it
            // back in initialize() instead of re-accumulating on resubmit.
            this._snap.push(JSON.parse(JSON.stringify(ds)));
            var period = state.currentPeriod;
            var results = { period: period };

            if (period === 1) {
                var exCost = d.numExCombatants * 21.56;
                var spCost = d.numSpecialists * 25;
                var adminCost = 60;
                var officeCost = d.numCities * 60;
                var matCost = d.numCities * 50;
                var legalCost = 60;
                var otherCost = Math.round(62 * d.numCities / 3);
                var newCost = Math.round(exCost + spCost + adminCost + officeCost + matCost + legalCost + otherCost);
                var totalFunds = 280 + 180 + 300;
                var gap = Math.max(0, newCost - totalFunds);
                var beneficiaries = Math.round(d.numExCombatants * 7.06);

                ds.annualCost = newCost;
                ds.annualRevenue = 280;
                ds.govFunding = 180;
                ds.ongFunding = 300;
                ds.totalFunds = totalFunds;
                ds.gap = gap;
                ds.beneficiaries = beneficiaries;
                ds.exCombatants = d.numExCombatants;
                ds.specialists = d.numSpecialists;
                ds.cities = d.numCities;
                ds.employees = d.numExCombatants + d.numSpecialists + Math.max(2, d.numCities * 2);

                results.annualCost = newCost;
                results.gap = gap;
                results.beneficiaries = beneficiaries;
                results.reputation = ds.reputation;
                results.breakEvenRevenue = Math.round(newCost / 0.65);
                results.employees = ds.employees;

            } else if (period === 2) {
                var strat = this.STRATEGIES[d.strategy];
                var gf = d.growthInvestment / 100;
                var projRevenue;

                ds.ongFunding = 0;
                ds.govFunding = 100;

                if (d.strategy === 'D') {
                    ds.annualCost = strat.cost;
                    projRevenue = strat.cost;
                    ds.totalFunds = strat.cost;
                    ds.gap = 0;
                } else {
                    projRevenue = Math.round(280 + strat.maxBonus * gf * strat.successRate);
                    ds.annualCost = strat.cost;
                    ds.annualRevenue = projRevenue;
                    ds.totalFunds = projRevenue + ds.govFunding;
                    ds.gap = Math.max(0, Math.round(ds.annualCost - ds.totalFunds));
                }
                ds.annualRevenue = projRevenue;
                ds.beneficiaries = Math.round(ds.beneficiaries * strat.impactMult);
                ds.reputation = Math.max(0, ds.reputation - strat.repCost);
                ds.strategy = d.strategy;

                results.annualCost = ds.annualCost;
                results.gap = ds.gap;
                results.beneficiaries = ds.beneficiaries;
                results.reputation = ds.reputation;
                results.projectedRevenue = projRevenue;
                results.strategy = d.strategy;

            } else if (period === 3) {
                var govBase = 0.25;
                var donorBase = 0.15;
                var investorBase = 0.30;

                if (ds.strategy === 'C') govBase += 0.20;
                if (ds.strategy === 'B') investorBase += 0.15;
                if (ds.strategy === 'A') donorBase += 0.10;
                if (ds.strategy === 'E') investorBase += 0.10;

                var govProb = Math.min(1, govBase * (1 + d.govAlloc / 50));
                var donorProb = Math.min(1, donorBase * (1 + d.donorAlloc / 50));
                var investorProb = Math.min(1, investorBase * (1 + d.investorAlloc / 50));

                var govFunded = Math.round(800 * govProb);
                var donorFunded = Math.round(400 * donorProb);
                var investorFunded = Math.round(300 * investorProb);
                var totalFunded = govFunded + donorFunded + investorFunded;

                var annualizedFunding = Math.round(totalFunded / 2);
                ds.externalFunding = annualizedFunding;
                ds.totalFunds = ds.annualRevenue + ds.govFunding + ds.externalFunding;
                ds.gap = Math.max(0, Math.round(ds.annualCost - ds.totalFunds));

                results.annualCost = ds.annualCost;
                results.gap = ds.gap;
                results.beneficiaries = ds.beneficiaries;
                results.reputation = ds.reputation;
                results.govFunded = govFunded;
                results.donorFunded = donorFunded;
                results.investorFunded = investorFunded;
                results.totalFunded = totalFunded;

            } else if (period === 4) {
                var fundingChange = 0;
                var repChange = 0;

                if (d.acceptFunding === 1) {
                    if (d.dueDiligence === 0) {
                        fundingChange = 1500;
                        repChange = -35;
                    } else if (d.dueDiligence === 1) {
                        fundingChange = 1050;
                        repChange = -15;
                    } else {
                        fundingChange = 0;
                        repChange = 10;
                    }
                } else {
                    repChange = 5 * (1 + d.dueDiligence);
                }
                repChange += (d.transparency - 1) * 5;

                var annualizedEthical = Math.round(fundingChange / 2);
                ds.externalFunding += annualizedEthical;
                ds.reputation = Math.min(100, Math.max(0, ds.reputation + repChange));
                ds.totalFunds = ds.annualRevenue + ds.govFunding + ds.externalFunding;
                ds.gap = Math.max(0, Math.round(ds.annualCost - ds.totalFunds));

                var finScore = 40 * Math.max(0, Math.min(1, 1 - ds.gap / 500));
                var impScore = 30 * Math.min(1, ds.beneficiaries / 127);
                var repScore = 20 * (ds.reputation / 100);
                var stratBonus = (ds.strategy && ds.gap < 200) ? 10 : 0;
                var sustainScore = Math.round(finScore + impScore + repScore + stratBonus);

                results.annualCost = ds.annualCost;
                results.gap = ds.gap;
                results.beneficiaries = ds.beneficiaries;
                results.reputation = ds.reputation;
                results.fundingChange = fundingChange;
                results.reputationChange = repChange;
                results.sustainabilityScore = sustainScore;
            }

            ds.gapHistory.push(results.gap);
            ds.beneficiaryHistory.push(results.beneficiaries);
            ds.reputationHistory.push(results.reputation);
            ds.fundingHistory.push(ds.totalFunds);

            // Advance the briefing/decision panel to the next round SYNCHRONOUSLY.
            // The framework increments currentPeriod right after this returns, so the
            // old deferred setTimeout read the already-incremented period and showed
            // the round-after-next controls (after Round 1 it revealed Round 3's panel).
            // validateDecisions band-aided it on the *next* submit, but the player had
            // already interacted with the wrong panel and their inputs were lost.
            // currentPeriod is still N here, so N+1 is correct. Skip past the last round.
            if (state.currentPeriod < (state.maxPeriods || 4)) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }

            return results;
        }

