        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var sustainScore = lastResult.sustainabilityScore || 0;
            var finalGap = lastResult.gap || 0;
            var finalBeneficiaries = lastResult.beneficiaries || 0;
            var finalReputation = lastResult.reputation || 0;

            var performance = 'Necesita Mejora';
            if (sustainScore > 80) performance = 'Excelente';
            else if (sustainScore > 60) performance = 'Bueno';
            else if (sustainScore > 40) performance = 'Regular';

            var insights = [];
            if (finalGap > 300) insights.push('La brecha financiera sigue siendo alta. Considere reducir costos o diversificar ingresos.');
            if (finalGap <= 100 && finalGap > 0) insights.push('Buena reducción de la brecha financiera. Cerca de la sostenibilidad.');
            if (finalGap === 0) insights.push('Brecha financiera eliminada. Excelente gestión financiera.');
            if (finalBeneficiaries < 80) insights.push('El impacto social se redujo significativamente. El balance entre sostenibilidad y misión es clave.');
            if (finalBeneficiaries >= 120) insights.push('Fuerte impacto social mantenido o ampliado.');
            if (finalReputation >= 90) insights.push('Integridad organizacional preservada. Esto fortalece la credibilidad a largo plazo.');
            if (finalReputation < 70) insights.push('La reputación fue comprometida. Para una empresa social, la integridad es el activo más valioso.');

            return {
                sustainabilityScore: sustainScore,
                performance: performance,
                insights: insights,
                finalGap: finalGap,
                finalBeneficiaries: finalBeneficiaries,
                finalReputation: finalReputation
            };
        }

